  'ستتوقف عن إدارة': 'You will stop managing',
  'فورًا، ويصل لصاحبه إشعار بإلغائك للتفويض. تستطيع العودة إليه من «المزيد ← التفويضات ← أشخاص فوّضوني» ما دام صاحبه لم يُنهِه. هل تريد المتابعة؟': 'immediately, and its owner will be notified. You can return to it from “More ← Delegations ← People who delegated me” as long as the owner has not ended it. Continue?',
