  'رفضها': 'Rejected it',
  'ستُغلق العهدة ولا يُصرف منها بعد ذلك. اكتب ما تم في التسوية (مثل: استلمت المتبقي نقدًا)، ثم اختر إبقاءها أو أرشفتها.': 'The custody will be closed and nothing more can be spent from it. Write what was done in the settlement (e.g. received the remainder in cash), then choose to keep or archive it.',
