  'اكتب «تاريخ الميلاد» في تعديل الملف الشخصي — والباقي يحسبه التطبيق لك.': 'Enter your birth date in Edit Profile — the app calculates the rest for you.',
  'الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، ولا يضيف التطبيق أي رسوم أخرى. قد يطبّق البنك أو المتجر رسوم تحويل العملة.': 'Displayed prices are final and include VAT where applicable; the app adds no other fees. Your bank or the store may apply currency conversion fees.',
  'الأهلية والحساب': 'Eligibility and account',
  'الاستخدام المقبول': 'Acceptable use',
  'الاسترداد': 'Refunds',
  'الاشتراك الشهري أو السنوي يتجدد تلقائيًا في نهاية كل مدة بنفس السعر حتى تلغي التجديد. الهدية لا تتجدد وتنتهي بنهاية مدتها.': 'Monthly or yearly subscriptions renew automatically at the end of each period at the same price until you cancel renewal. Gifts do not renew and end when their period ends.',
  'الاشتراك المُهدى يبدأ يوم تفعيل كوده من المُهدى إليه، وينتهي بنهاية مدته دون تجديد. لا تُسترد قيمة الهدية بعد شرائها أو تفعيلها، ولا تُستبدل نقدًا.': 'A gifted subscription starts on the day the recipient redeems its code and ends at the end of its period without renewal. Gifts are non-refundable once bought or redeemed and cannot be exchanged for cash.',
  'التجديد التلقائي': 'Auto-renewal',
  'التطبيق أداة لتنظيم وتسجيل الأموال والالتزامات والأصول والعلاقات. ما يعرضه من أرقام وتنبيهات وتقارير مبني على ما تدخله أنت، ولا يُعد استشارة مالية أو قانونية أو محاسبية أو ضريبية.': 'The app is a tool to organize and record money, commitments, assets and relationships. Its figures, alerts and reports are based on what you enter and are not financial, legal, accounting or tax advice.',
  'التعديلات على الشروط': 'Changes to these terms',
  'التواصل بشأن المدفوعات': 'Payment inquiries',
  'التوفر والتعديلات على الخدمة': 'Availability and changes to the service',
  'الدفع داخل التطبيق لم يُفعَّل بعد، فتُفعَّل الباقة الآن تجريبيًا بلا أي خصم. يبدأ الاشتراك فورًا ويتجدد تلقائيًا في نهاية المدة حتى تلغي التجديد، وتتغير صلاحيات الأقسام فورًا.': 'In-app payment is not enabled yet, so the plan is activated now on a trial basis with no charge. The subscription starts immediately and renews automatically at the end of the period until you cancel renewal; section permissions change immediately.',
  'الرسوم والضرائب': 'Fees and taxes',
  'المشاركة مع مستخدمين آخرين': 'Sharing with other users',
  'النظام الواجب التطبيق': 'Governing law',
  'بدأ في': 'Started on',
  'بعد الإلغاء': 'After cancellation',
  'بنفس السعر والمدة.': 'at the same price and period.',
  'بياناتك ومحتواك': 'Your data and content',
  'تاريخ الميلاد غير صحيح — اكتبه يوم/شهر/سنة مثل 17/9/1984': 'Invalid birth date — enter it as day/month/year, e.g. 17/9/1984',
  'تخضع هذه الشروط لأنظمة المملكة العربية السعودية، وتختص محاكمها بالنظر في أي نزاع ينشأ عنها، دون إخلال بحقوقك النظامية في بلد إقامتك.': 'These terms are governed by the laws of the Kingdom of Saudi Arabia, whose courts have jurisdiction over any dispute arising from them, without prejudice to your statutory rights in your country of residence.',
  'تنبيه: عند إلغاء الاشتراك أو الهدية لا تُسترد المبالغ المدفوعة، ويبقى الاشتراك فعّالًا حتى نهاية مدته.': 'Note: cancelling a subscription or gift does not refund amounts paid; the subscription stays active until the end of its period.',
  'تنظّم هذه الشروط استخدامك تطبيق Fundly وخدماته. باستخدامك التطبيق فأنت توافق عليها وعلى سياسة الخصوصية، فإن لم توافق فتوقف عن الاستخدام.': 'These terms govern your use of the Fundly app and its services. By using the app you agree to them and to the Privacy Policy; if you do not agree, stop using the app.',
  'تواصل بشأن المدفوعات': 'Contact us about payments',
  'تُقدَّم الخدمة «كما هي». وبالقدر الذي تسمح به الأنظمة لا نتحمل المسؤولية عن أي خسارة غير مباشرة، أو عن قرارات اتخذتها بناءً على بيانات أدخلتها، أو عن فقد بيانات محفوظة على جهازك فقط.': 'The service is provided "as is". To the extent permitted by law, we are not liable for any indirect loss, for decisions you made based on data you entered, or for loss of data stored only on your device.',
  'حدود المسؤولية': 'Limitation of liability',
  'سيتجدد اشتراكك تلقائيًا في': 'Your subscription will renew automatically on',
  'شروط الاستخدام': 'Terms of Use',
  'شروط الاشتراك والدفع': 'Subscription and payment terms',
  'شروط الخدمة والاشتراكات والمدفوعات': 'Service, subscription and payment terms',
  'طبيعة الخدمة': 'Nature of the service',
  'عند إسناد عهدة أو ربط دين أو إضافة أعضاء إلى التزام مشترك، يرى الطرف الآخر العنصر المشترك وما يسجّله فيه. كل طرف مسؤول عمّا يسجّله أو يعتمده، والتطبيق وسيلة توثيق ولا يضمن وفاء أي طرف بالتزاماته تجاه الآخر.': 'When you assign a custody, link a debt or add members to a shared commitment, the other party sees the shared item and what is recorded in it. Each party is responsible for what it records or approves; the app is a documentation tool and does not guarantee that any party meets its obligations to the other.',
  'قد نحدّث هذه الشروط، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': 'We may update these terms and will notify you in the app of any material change before it takes effect. Continuing to use the app afterwards means you accept the updated version.',
  'لأي استفسار عن الدفع أو الفواتير أو الاسترداد راسلنا من «تواصل معنا» على بريد الدعم، مع تاريخ العملية ورقم الإصدار.': 'For any question about payments, invoices or refunds, write to us from "Contact us" at the support email, including the transaction date and app version.',
  'لأي سؤال عن هذه الشروط أو عن الاشتراكات والمدفوعات راسلنا على بريد الدعم: support@fundly.app': 'For any question about these terms or about subscriptions and payments, email support: support@fundly.app',
  'لا تُسترد المبالغ المدفوعة عن مدة بدأت، ولا قيمة الهدية بعد شرائها أو تفعيلها، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.': 'Amounts paid for a period that has started are non-refundable, as are gifts once bought or redeemed, except where required by law or by the policy of the store used for payment.',
  'لا يُقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة، ثم يعود حسابك إلى الباقة الأساسية وتبقى كل بياناتك محفوظة.': 'The subscription is not cut off immediately: it stays active until the end of the paid period, then your account returns to the basic plan and all your data is kept.',
  'متى يبدأ الاشتراك': 'When the subscription starts',
  'مفعّل': 'On',
  'ملغى — يبقى فعّالًا حتى نهاية المدة': 'Cancelled — stays active until the end of the period',
  'من هذه الصفحة بزر «إلغاء التجديد التلقائي»، أو من إدارة الاشتراكات في متجر التطبيقات الذي دفعت منه، قبل موعد التجديد بيوم على الأقل.': 'From this page with "Cancel auto-renewal", or from subscription management in the app store you paid through, at least one day before the renewal date.',
  'نعمل على أن تكون الخدمة متاحة باستمرار، لكن قد تتوقف مؤقتًا للصيانة أو لأسباب خارجة عن إرادتنا. وقد نطوّر الميزات أو نعدّلها، ونُبلغك داخل التطبيق بأي تغيير جوهري يمس اشتراكك.': 'We aim to keep the service available at all times, but it may pause temporarily for maintenance or reasons beyond our control. We may develop or change features and will notify you in the app of any material change affecting your subscription.',
  'هدية — لا تتجدد': 'Gift — does not renew',
  'يبدأ فور تأكيد الدفع وتُحسب مدته من يوم الدفع. والهدية تبدأ يوم تفعيل كودها من المُهدى إليه، لا يوم شرائها.': 'It starts as soon as payment is confirmed and its period counts from the payment day. A gift starts on the day the recipient redeems its code, not the day it was bought.',
  'يبقى اشتراكك فعّالًا حتى': 'Your subscription stays active until',
  'يتجدد تلقائيًا في': 'Renews automatically on',
  'يتجدد في': 'Renews on',
  'يمكنك حذف حسابك في أي وقت من الإعدادات. ويحق لنا تعليق الحساب أو إيقافه عند مخالفة هذه الشروط، مع إبلاغك بالسبب ما لم يمنع ذلك نظام.': 'You can delete your account at any time from Settings. We may suspend or terminate an account that breaches these terms, informing you of the reason unless the law prevents it.',
  'يوم/شهر/سنة — مثل 17/9/1984': 'Day/month/year — e.g. 17/9/1984',
  'يُمنع استخدام التطبيق في أي نشاط مخالف للأنظمة أو في الاحتيال أو انتحال الشخصية، أو محاولة الوصول إلى حسابات أو بيانات غيرك، أو تعطيل الخدمة، أو نسخ التطبيق أو تفكيكه أو إعادة بيعه.': 'You may not use the app for any unlawful activity, fraud or impersonation, attempt to access other people\'s accounts or data, disrupt the service, or copy, reverse-engineer or resell the app.',
  '• التطبيق لمن بلغ 18 عامًا.\n• أنت مسؤول عن صحة بيانات حسابك، وعن سرية كلمة المرور ورمز قفل التطبيق، وعن كل ما يتم من حسابك.\n• أبلغنا فورًا إن اشتبهت في استخدام حسابك دون إذنك.': '• The app is for people aged 18 or over.\n• You are responsible for the accuracy of your account data, the secrecy of your password and app lock code, and everything done through your account.\n• Tell us immediately if you suspect your account is being used without your permission.',
  '• ما تدخله من بيانات ومستندات يبقى ملكك، وتمنحنا حق معالجته بالقدر اللازم لتقديم الخدمة فقط وفق سياسة الخصوصية.\n• أنت مسؤول عن مشروعية ما تسجّله من بيانات أشخاص آخرين وعن حصولك على ما يلزم لذلك.': '• The data and documents you enter remain yours; you grant us the right to process them only as needed to provide the service, in line with the Privacy Policy.\n• You are responsible for the lawfulness of other people\'s data you record and for obtaining what is required to do so.',
  '• يبدأ الاشتراك فور تأكيد الدفع وتُحسب مدته من يوم الدفع.\n• يتجدد الاشتراك الشهري أو السنوي تلقائيًا بنفس السعر حتى تلغي التجديد من صفحة الاشتراكات أو من متجر التطبيقات قبل موعد التجديد بيوم على الأقل.\n• إلغاء التجديد لا يقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة ثم يعود الحساب إلى الباقة الأساسية وتبقى البيانات محفوظة.\n• لا تُسترد المبالغ المدفوعة عن مدة بدأت، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.\n• الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، وقد يطبّق البنك أو المتجر رسوم تحويل العملة.': '• A subscription starts as soon as payment is confirmed and its period counts from the payment day.\n• Monthly or yearly subscriptions renew automatically at the same price until you cancel renewal from the Subscriptions page or the app store, at least one day before the renewal date.\n• Cancelling renewal does not cut off the subscription immediately: it stays active until the end of the paid period, then the account returns to the basic plan and data is kept.\n• Amounts paid for a period that has started are non-refundable, except where required by law or by the policy of the store used for payment.\n• Displayed prices are final and include VAT where applicable; your bank or the store may apply currency conversion fees.',
