  'تسوية العهدة قبل الإلغاء': 'Settle custody before cancelling',
  'لا تُلغى العهدة بدون تسوية. اكتب سبب التسوية ثم اختر إلغاء العهدة أو تسويتها وأرشفتها.': 'Custody cannot be cancelled without settlement. Write the settlement reason, then choose to cancel the custody or settle and archive it.',
