  'مزامنة البيانات': 'Data sync',
  'نفس بياناتك في كل جوال تدخل منه': 'Your same data on every phone you sign in from',
  'بياناتك محفوظة في حسابك وتظهر في أي جوال تدخل منه بنفس الحساب. تتم المزامنة تلقائيًا كل 30 ثانية وعند فتح التطبيق والخروج منه. افتح هذه الصفحة في الجوالين: يجب أن يكون الحساب والأرقام نفسها.': 'Your data is saved in your account and appears on any phone you sign in to with the same account. Sync runs automatically every 30 seconds and when you open or leave the app. Open this page on both phones: the account and the numbers should match.',
