  'موقّع': 'signed',
  'الصفحة': 'Page',
  'آخر تحديث: 12 أكتوبر 2026': 'Last updated: 12 October 2026',
  'توضح هذه السياسة كيف يجمع تطبيق Fundly بياناتك ويستخدمها ويحميها، وحقوقك عليها. باستخدامك التطبيق فأنت توافق على ما ورد فيها.': 'This Policy explains how the Fundly app collects, uses and protects your data, and your rights in relation to it. By using the App, you agree to the terms set out herein.',
  'من نحن ونطاق السياسة': 'Who We Are and Scope of This Policy',
  'تطبيق Fundly («التطبيق»، «نحن») لإدارة الأموال والالتزامات والأصول والعلاقات. تسري هذه السياسة على كل ما يُجمع أو يُعالَج عبر التطبيق وخدماته، وتُطبَّق وفق نظام حماية البيانات الشخصية في المملكة العربية السعودية ولائحته التنفيذية، وأنظمة حماية البيانات المعمول بها في بلد المستخدم بالقدر الذي ينطبق عليه.': 'Fundly (the “App”, “we”) is an app for managing finances, obligations, assets and relationships. This Policy applies to all data collected or processed through the App and its services, and is applied in accordance with the Personal Data Protection Law (PDPL) of the Kingdom of Saudi Arabia and its Implementing Regulations, as well as the data protection laws in force in the user\'s country to the extent applicable to them.',
  'البيانات التي نجمعها': 'Data We Collect',
  '• بيانات الحساب: الاسم، ورقم الهاتف أو البريد الإلكتروني المستخدم في الدخول، والرقم التعريفي الذي يُنشئه التطبيق لك.\n• البيانات التي تدخلها بنفسك: الالتزامات والمصروفات والدخل والديون والعهد والأقساط، وبيانات العقارات والأنشطة والمركبات وعقود الإيجار والدفعات، والمستندات والمرفقات والنماذج والتقارير.\n• بيانات أشخاص آخرين تسجّلها أنت: مثل المستأجرين والمؤجرين والأفراد والجهات وأرقام هوياتهم وهواتفهم.\n• الموقع الجغرافي: عند ضغطك زر جلب الموقع فقط، وبعد إذنك.\n• بيانات تقنية محدودة يلزمها التشغيل، مثل سجلات الاتصال لدى مزوّد الاستضافة لأغراض الأمان.\nلا نستخدم أدوات إعلانات أو تتبّع أو تحليلات سلوكية من أطراف ثالثة.': '• Account data: your name, the phone number or email address used to sign in, and the identification number the App generates for you.\n• Data you enter yourself: obligations, expenses, income, debts, custody items and instalments; data on properties, business activities, vehicles, lease contracts and payments; and documents, attachments, templates and reports.\n• Data about other persons that you record: such as tenants, landlords, individuals and entities, and their ID and phone numbers.\n• Geographic location: only when you tap the “Get location” button, and with your permission.\n• Limited technical data required for operation, such as connection logs kept by the hosting provider for security purposes.\nWe do not use third-party advertising, tracking or behavioural analytics tools.',
  'لماذا نعالج بياناتك': 'Why We Process Your Data',
  '• تقديم خدمات التطبيق وحفظ سجلاتك ومزامنتها بين أجهزتك.\n• إنشاء التذكيرات والتنبيهات والتقارير التي تطلبها.\n• تنفيذ المشاركة التي تختارها مع مستخدمين آخرين (العهد والديون والالتزامات المشتركة والتفويضات).\n• الرد على طلبات الدعم.\n• حماية الحسابات ومنع الاستخدام غير المشروع والالتزام بالأنظمة.\nنعالج البيانات لتنفيذ الخدمة التي طلبتها، وبموافقتك فيما يحتاج موافقة (الموقع والكاميرا والصور)، وللوفاء بالتزاماتنا النظامية. ولا نستخدمها لأي غرض آخر دون إبلاغك.': '• Providing the App\'s services, storing your records and synchronising them across your devices.\n• Generating the reminders, alerts and reports you request.\n• Carrying out the sharing you choose with other users (custody items, debts, shared obligations and delegations).\n• Responding to support requests.\n• Protecting accounts, preventing unlawful use and complying with applicable laws.\nWe process data to perform the service you have requested, on the basis of your consent where consent is required (location, camera and photos), and to fulfil our legal obligations. We do not use it for any other purpose without informing you.',
  'أين تُحفظ بياناتك': 'Where Your Data Is Stored',
  '• السجلات الأساسية والمرفقات المرفوعة تُحفظ لدى مزوّد الاستضافة السحابية (Supabase)، مقيّدة بحسابك بضوابط وصول على مستوى السجل، فلا يطّلع عليها حساب آخر إلا ما تشاركه أنت.\n• تُحفظ على جهازك فقط: التفضيلات، وصورة الملف الشخصي، ورمز قفل التطبيق، والتوقيع والختم والشعار، ودليل الأفراد والجهات، والمستندات العامة، والتذكيرات المحلية. حذف التطبيق يحذف هذه البيانات من الجهاز.\n• قد تُعالَج البيانات على خوادم خارج بلدك، ونلتزم عندئذ بالضمانات التي تشترطها الأنظمة لنقل البيانات خارج الحدود.': '• Core records and uploaded attachments are stored with our cloud hosting provider (Supabase) and restricted to your account by row-level access controls, so that no other account can view them except what you choose to share.\n• Stored only on your device: preferences, profile photo, app lock code, signature, stamp and logo, the directory of individuals and entities, general documents, and local reminders. Deleting the App deletes this data from the device.\n• Data may be processed on servers outside your country; in such cases, we comply with the safeguards required by law for cross-border data transfers.',
  'مشاركة البيانات والإفصاح عنها': 'Data Sharing and Disclosure',
  '• لا نبيع بياناتك ولا نؤجّرها ولا نشاركها لأغراض تسويقية.\n• المشاركة داخل التطبيق تتم بطلبك: عند إسناد عهدة أو دين أو إضافة عضو بالرقم التعريفي يرى الطرف الآخر العنصر المشترك واسمك فقط، ولا يُكشف هاتفك أو عنوانك إلا بموافقتك.\n• ما تشاركه عبر زر المشاركة أو الطباعة (PDF أو صورة) يخرج بإرادتك وعبر التطبيق الذي تختاره.\n• نستعين بمزوّدي خدمة (الاستضافة والتخزين) يعالجون البيانات نيابةً عنّا وفق التزامات تعاقدية بالسرية والأمان.\n• قد نفصح عن البيانات إذا ألزمنا بذلك نظام أو أمر قضائي أو جهة مختصة.': '• We do not sell or rent your data, nor do we share it for marketing purposes.\n• Sharing within the App takes place at your request: when you assign a custody item or a debt, or add a member by identification number, the other party sees only the shared item and your name; your phone number or address is not disclosed without your consent.\n• Anything you share via the share or print button (PDF or image) leaves the App at your own discretion and through the app you choose.\n• We engage service providers (hosting and storage) that process data on our behalf under contractual obligations of confidentiality and security.\n• We may disclose data where required to do so by law, a court order or a competent authority.',
  '• الكاميرا والصور والملفات: لإرفاق المستندات والصور والختم والشعار وصورة الملف الشخصي.\n• الموقع: لتعبئة حقل الموقع عند طلبك فقط.\n• الإنترنت: لمزامنة بياناتك.\nيمكنك سحب أي إذن من إعدادات جهازك في أي وقت، وتبقى بقية خصائص التطبيق تعمل.': '• Camera, photos and files: to attach documents, images, stamps, logos and your profile photo.\n• Location: to fill in the location field, only at your request.\n• Internet: to synchronise your data.\nYou may withdraw any permission from your device settings at any time, and the App\'s other features will continue to work.',
  'الاحتفاظ بالبيانات': 'Data Retention',
  'نحتفظ ببياناتك ما دام حسابك قائمًا. ما تحذفه ينتقل إلى سلة المهملات حتى تحذفه نهائيًا. وعند حذف الحساب تُحذف بياناته من أنظمتنا خلال مدة لا تتجاوز 30 يومًا، عدا ما يلزم الاحتفاظ به نظامًا، وتُزال من النسخ الاحتياطية وفق دورتها.': 'We retain your data for as long as your account remains active. Items you delete are moved to the Trash until you delete them permanently. When an account is deleted, its data is erased from our systems within a period not exceeding 30 days, except for data that must be retained by law, and is removed from backups in accordance with their rotation cycle.',
  'أمن البيانات': 'Data Security',
  '• تشفير الاتصال بين التطبيق والخوادم (TLS).\n• ضوابط وصول تقصر كل سجل على صاحبه ومن يشاركه.\n• قفل التطبيق برمز، وخيار إخفاء المبالغ.\nلا توجد وسيلة نقل أو تخزين آمنة تمامًا، لذا نوصيك بحماية جهازك وعدم مشاركة رمز القفل.': '• Encryption of the connection between the App and the servers (TLS).\n• Access controls that restrict each record to its owner and those with whom it is shared.\n• App lock with a passcode, and an option to hide amounts.\nNo method of transmission or storage is completely secure; we therefore recommend that you protect your device and do not share your lock code.',
  'حقوقك': 'Your Rights',
  'وفق الأنظمة المعمول بها لك الحق في:\n• العلم بكيفية جمع بياناتك ومعالجتها.\n• الوصول إلى بياناتك والحصول على نسخة منها.\n• تصحيحها أو تحديثها.\n• طلب حذفها أو إتلافها.\n• الرجوع عن موافقتك فيما بُني عليها.\n• تقديم شكوى إلى الجهة المختصة بحماية البيانات في بلدك (في المملكة العربية السعودية: الهيئة السعودية للبيانات والذكاء الاصطناعي «سدايا»).\nنرد على طلبك خلال 30 يومًا من استلامه.': 'Under applicable laws, you have the right to:\n• Be informed of how your data is collected and processed.\n• Access your data and obtain a copy of it.\n• Have it corrected or updated.\n• Request its deletion or destruction.\n• Withdraw your consent where processing is based on it.\n• Lodge a complaint with the competent data protection authority in your country (in the Kingdom of Saudi Arabia: the Saudi Data & AI Authority (SDAIA)).\nWe will respond to your request within 30 days of receiving it.',
  'حذف الحساب': 'Account Deletion',
  'يمكنك حذف أي سجل من داخل شاشته في أي وقت. ولحذف حسابك وكل بياناته استخدم زر «طلب حذف الحساب» أسفل هذه الصفحة، أو راسلنا على بريد الدعم من البريد أو الرقم المرتبط بحسابك، وسنتحقق من الطلب وننفّذه.': 'You may delete any record from within its screen at any time. To delete your account and all of its data, use the “Request Account Deletion” button at the bottom of this page, or write to us at the support email address from the email address or phone number linked to your account; we will verify the request and carry it out.',
  'بيانات الآخرين التي تدخلها': 'Data of Others That You Enter',
  'عند تسجيلك بيانات أشخاص آخرين (كالمستأجرين أو الأفراد أو أطراف العقود) فأنت مسؤول عن أن يكون لديك أساس نظامي لذلك، وأن تستخدمها لأغراضك المشروعة فقط.': 'When you record data about other persons (such as tenants, individuals or contracting parties), you are responsible for having a lawful basis for doing so and for using that data solely for your legitimate purposes.',
  'الاشتراكات والمدفوعات': 'Subscriptions and Payments',
  'عند تفعيل الاشتراكات المدفوعة تتم عمليات الدفع عبر متاجر التطبيقات أو بوابات دفع مرخّصة، ولا نحفظ بيانات بطاقتك.': 'When paid subscriptions are enabled, payments are processed through app stores or licensed payment gateways, and we do not store your card details.',
  'الأطفال': 'Children',
  'التطبيق موجّه لمن بلغ 18 عامًا، ولا نجمع عن قصد بيانات من هم دون ذلك.': 'The App is intended for persons aged 18 and over, and we do not knowingly collect data from anyone under that age.',
  'التعديلات على السياسة': 'Changes to This Policy',
  'قد نحدّث هذه السياسة، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': 'We may update this Policy and will notify you within the App of any material change before it takes effect. Your continued use of the App after the effective date constitutes your acceptance of the updated version.',
  'التواصل معنا': 'Contact Us',
  'لأي سؤال أو طلب يتعلق بخصوصيتك راسلنا على بريد الدعم: support@fundly.app': 'For any question or request regarding your privacy, write to us at our support email address: support@fundly.app',
  'طلب حذف الحساب': 'Request Account Deletion',
  'سيُفتح بريدك برسالة جاهزة لطلب حذف حسابك وكل بياناته نهائيًا. أرسلها من البريد أو الرقم المرتبط بحسابك. هل تريد المتابعة؟': 'Your email app will open with a ready-made message requesting the permanent deletion of your account and all of its data. Send it from the email address or phone number linked to your account. Do you want to continue?',
  'تعذّر فتح البريد — نُسخ بريد الدعم لتراسلنا منه': 'Unable to open email — the support email address has been copied so you can contact us',
