  'الدفع داخل التطبيق لم يُفعَّل بعد، فتُفعَّل الباقة الآن تجريبيًا بلا أي خصم. تتغير صلاحيات الأقسام فورًا.': 'In-app payment is not enabled yet, so the plan is activated now as a trial with no charge. Section permissions change immediately.',
