  'التوقيع: ..................': 'Signature: ..................',
  'إنه في يوم {تاريخ تحرير العقد} بمدينة {مكان تحرير العقد} تم الاتفاق بين كلٍّ من الطرف الأول (المؤجر): {اسم المؤجر}، والطرف الثاني (المستأجر): {اسم المستأجر}، وقد أقرّ الطرفان بأهليتهما للتعاقد واتفقا على ما يلي:': 'On {تاريخ تحرير العقد} in {مكان تحرير العقد}, an agreement was made between the first party (lessor): {اسم المؤجر}, and the second party (tenant): {اسم المستأجر}. Both parties confirm their legal capacity to contract and agree as follows:',
  'أقرّ أنا الموقّع أدناه {اسم المدين}، حامل الهوية رقم {رقم هوية المدين}، بأنني استلمت من {اسم الدائن}، حامل الهوية رقم {رقم هوية الدائن}، مبلغًا وقدره {المبلغ} ({المبلغ كتابةً}) على سبيل {نوع المبلغ}، وذلك بتاريخ {تاريخ الاستلام}.': 'I, the undersigned {اسم المدين}, holder of ID number {رقم هوية المدين}, acknowledge that I have received from {اسم الدائن}, holder of ID number {رقم هوية الدائن}, the sum of {المبلغ} ({المبلغ كتابةً}) as {نوع المبلغ}, on {تاريخ الاستلام}.',
  'إنه في يوم {تاريخ تحرير العقد} تم الاتفاق بين كلٍّ من الطرف الأول: {الطرف الأول}، والطرف الثاني: {الطرف الثاني}، وقد أقرّ الطرفان بأهليتهما للتعاقد واتفقا على ما يلي:': 'On {تاريخ تحرير العقد}, an agreement was made between the first party: {الطرف الأول}, and the second party: {الطرف الثاني}. Both parties confirm their legal capacity to contract and agree as follows:',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ إليه عند انتهاء العقد بعد خصم قيمة أي أضرار أو مستحقات قائمة.': 'The tenant has paid a deposit of {مبلغ التأمين}, refundable at the end of the contract after deducting any damages or outstanding dues.',
  'شروط إضافية: {شروط إضافية}': 'Additional terms: {شروط إضافية}',
  'حُرِّر هذا العقد من نسختين، بيد كل طرف نسخة للعمل بموجبها.': 'This contract is made in two copies, one for each party to act upon.',
  'مدة العقد من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، ولا يُجدَّد إلا باتفاق مكتوب بين الطرفين.': 'The contract term is from {تاريخ بداية العقد} to {تاريخ نهاية العقد}, and it is renewed only by written agreement between the parties.',
  'الأجرة السنوية {قيمة الإيجار السنوي}، تُدفع {طريقة الدفع} مقدمًا في مواعيد استحقاقها، ولا يحق للمستأجر تأخيرها أو الامتناع عنها.': 'The annual rent is {قيمة الإيجار السنوي}, payable in advance ({طريقة الدفع}) on its due dates; the tenant may not delay or withhold it.',
  'إذا تأخر المستأجر عن سداد الأجرة أو أخلّ بأي من التزاماته، يحق للمؤجر المطالبة بفسخ العقد وبما يستحقه وفق الأنظمة المعمول بها.': 'If the tenant is late paying the rent or breaches any obligation, the lessor may claim termination of the contract and any amounts due under applicable law.',
  'سبب الدين: {سبب الدين}.': 'Reason for the debt: {سبب الدين}.',
  'أتعهد بردّ المبلغ كاملًا إلى الدائن أو من يفوّضه في موعد أقصاه {تاريخ السداد}، وطريقة السداد: {طريقة السداد}.': 'I undertake to repay the full amount to the creditor or their authorized representative no later than {تاريخ السداد}. Repayment method: {طريقة السداد}.',
  'يُسدَّد المبلغ على {عدد الأقساط} أقساط، قيمة كل قسط {قيمة القسط}.': 'The amount is repaid in {عدد الأقساط} installments of {قيمة القسط} each.',
  'يُعدّ هذا الإيصال سندًا بالمبلغ، ويحق للدائن عند التأخر عن السداد المطالبة به بالطرق النظامية.': 'This receipt is proof of the debt, and if repayment is late the creditor may claim it through legal means.',
  'وهذا إقرار مني بذلك وأنا بكامل أهليتي المعتبرة شرعًا ونظامًا.': 'I make this acknowledgment in full legal capacity.',
  'يستعمل المستأجر العقار للغرض المتفق عليه ({الغرض من الإيجار}) فقط، ولا يحق له التأجير من الباطن أو التنازل عن العقد إلا بموافقة كتابية من المؤجر.': 'The tenant shall use the property only for the agreed purpose ({الغرض من الإيجار}) and may not sublet or assign the contract without the lessor’s written consent.',
  'فواتير الخدمات (الكهرباء والماء والاتصالات) على {فواتير الخدمات على}، والصيانة البسيطة على {الصيانة البسيطة على}، والصيانة الأساسية والإنشائية على {الصيانة الأساسية على}.': 'Utility bills (electricity, water and telecom) are paid by the {فواتير الخدمات على}; minor maintenance by the {الصيانة البسيطة على}; major and structural maintenance by the {الصيانة الأساسية على}.',
  'لا يجوز للمستأجر إجراء أي تعديلات أو إنشاءات في العقار إلا بموافقة كتابية من المؤجر.': 'The tenant may not make any alterations or construction in the property without the lessor’s written consent.',
  'يلتزم المستأجر بالمحافظة على العقار وتسليمه عند انتهاء العقد بالحالة التي استلمه بها، عدا الاستهلاك المعتاد.': 'The tenant shall maintain the property and return it at the end of the contract in the condition received, except for normal wear and tear.',
  'منح المؤجر المستأجر فترة سماح للتجهيز مدتها {فترة السماح للتجهيز} لا تُحتسب فيها أجرة.': 'The lessor grants the tenant a fit-out grace period of {فترة السماح للتجهيز} with no rent charged.',
  'يستعمل المستأجر المحل لممارسة نشاط ({نوع النشاط}) تحت الاسم التجاري ({الاسم التجاري}) فقط، ولا يحق له تغيير النشاط أو التأجير من الباطن إلا بموافقة كتابية من المؤجر.': 'The tenant shall use the shop only for the activity ({نوع النشاط}) under the trade name ({الاسم التجاري}) and may not change the activity or sublet without the lessor’s written consent.',
  'يلتزم المستأجر باستخراج التراخيص اللازمة لنشاطه وتجديدها قبل انتهائها، ويتحمّل وحده أي مخالفات أو غرامات تنشأ عن نشاطه.': 'The tenant shall obtain the licenses required for the activity and renew them before expiry, and alone bears any violations or fines arising from the activity.',
  'فواتير الخدمات على {فواتير الخدمات على}، والصيانة على {الصيانة على}، واللوحات والديكور على {اللوحات والديكور على}.': 'Utility bills are paid by the {فواتير الخدمات على}; maintenance by the {الصيانة على}; signage and decor by the {اللوحات والديكور على}.',
  'عند انتهاء العقد يسلّم المستأجر المحل خاليًا من الشواغل وبالحالة التي استلمه بها، وتؤول التحسينات الثابتة للمؤجر ما لم يُتفق على غير ذلك.': 'At the end of the contract the tenant returns the shop vacant and in the condition received; fixed improvements pass to the lessor unless otherwise agreed.',
  'مدة الإيجار من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، وأجرة المركبة {قيمة الإيجار} على أساس {أساس التأجير}.': 'The rental period is from {تاريخ بداية العقد} to {تاريخ نهاية العقد}, and the vehicle rent is {قيمة الإيجار} on a {أساس التأجير} basis.',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ عند إعادة المركبة سليمة بعد خصم أي مستحقات.': 'The tenant has paid a deposit of {مبلغ التأمين}, refundable when the vehicle is returned undamaged after deducting any dues.',
  'استلم المستأجر المركبة بحالة جيدة، وقراءة العداد {قراءة العداد عند التسليم} كم، ومستوى الوقود {مستوى الوقود عند التسليم}، ويعيدها بالحالة نفسها.': 'The tenant received the vehicle in good condition with an odometer reading of {قراءة العداد عند التسليم} km and fuel level {مستوى الوقود عند التسليم}, and shall return it in the same condition.',
  'الكيلومترات المسموحة {الكيلومترات المسموحة} كم، وما زاد عليها يُحتسب بواقع {رسوم الكيلومتر الإضافي} لكل كيلومتر.': 'Allowed distance is {الكيلومترات المسموحة} km; any excess is charged at {رسوم الكيلومتر الإضافي} per kilometer.',
  'المستأجر مسؤول عن المخالفات المرورية والحوادث وما يترتب عليها طوال مدة الإيجار، وعليه إبلاغ المؤجر والجهات المختصة فور وقوع أي حادث.': 'The tenant is responsible for traffic violations, accidents and their consequences during the rental period, and must notify the lessor and the authorities immediately after any accident.',
  'لا يحق للمستأجر السماح لغيره بقيادة المركبة، أو استعمالها في غير الغرض المعتاد، أو الخروج بها خارج الدولة إلا بموافقة كتابية من المؤجر.': 'The tenant may not let others drive the vehicle, use it for any unusual purpose, or take it out of the country without the lessor’s written consent.',
  'الوقود على {الوقود على}، والصيانة الدورية على {الصيانة الدورية على}، ونوع التأمين على المركبة: {التأمين على المركبة}.': 'Fuel is paid by the {الوقود على}; routine maintenance by the {الصيانة الدورية على}; vehicle insurance: {التأمين على المركبة}.',
  'التأخر في إعادة المركبة عن الموعد المحدد يُحتسب بأجرة يوم كامل عن كل يوم تأخير أو جزء منه.': 'Late return of the vehicle is charged a full day’s rent for each day or part of a day of delay.',
  'موضوع العقد: {موضوع العقد}': 'Contract subject: {موضوع العقد}',
  'قيمة العقد {قيمة العقد}، تُدفع {طريقة الدفع}.': 'The contract value is {قيمة العقد}, payable as {طريقة الدفع}.',
  'مدة العقد من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}.': 'The contract term is from {تاريخ بداية العقد} to {تاريخ نهاية العقد}.',
  'يلتزم الطرف الأول بما يلي: {التزامات الطرف الأول}': 'The first party undertakes the following: {التزامات الطرف الأول}',
  'يلتزم الطرف الثاني بما يلي: {التزامات الطرف الثاني}': 'The second party undertakes the following: {التزامات الطرف الثاني}',
  'في حال إخلال أي طرف بالتزاماته يحق للطرف الآخر المطالبة بالتعويض وفسخ العقد وفق الأنظمة المعمول بها.': 'If either party breaches its obligations, the other party may claim compensation and terminate the contract under applicable law.',
