  'يرجى الإلغاء بعد عمل التسوية.': 'Please cancel only after the settlement.',
  'سيصبح العقد «ملغي» وتتحول الوحدة إلى شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': 'The contract will become "Cancelled" and the unit will be vacant. Continue?\n\nNote: after cancelling, this contract and its dues disappear from reports. If you need the unit or its information in the future, archiving is better than cancelling.',
  'أُلغي العقد وأصبحت الوحدة شاغرة': 'Contract cancelled and the unit is now vacant',
  'تعذر إلغاء العقد': 'Could not cancel the contract',
  'الوحدة شاغرة ولا يوجد عقد لإلغائه': 'The unit is vacant; there is no contract to cancel',
  'سيُلغى عقد الإيجار بعد عمل التسوية، ويصبح العقد «ملغي» والوحدة شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': 'The lease will be cancelled after settlement; the contract becomes "Cancelled" and the unit vacant. Continue?\n\nNote: after cancelling, this contract and its dues disappear from reports. If you need the unit or its information in the future, archiving is better than cancelling.',
